import { workflow, node, trigger, ifElse, expr } from '@n8n/workflow-sdk';

// 20 - NOYA Draft Revalidation (Adam, 7 Oct 2026). Ready drafts older than 14 days are revalidated, never blindly redrafted:
// company still qualified, still cold, no new Gmail, no newer duplicate (revalidation_queue), why-now date not passed, and one
// LinkedIn search confirming the person still holds the role. revalidation_save keeps, closes, re-searches the person or frees
// the account for a fresh draft. Never contacts anyone. Generated by n8n/build_w20_22.py.

const manualRun = trigger({ type: 'n8n-nodes-base.manualTrigger', version: 1, config: { name: 'Manual Run' } });
const schedule = trigger({ type: 'n8n-nodes-base.scheduleTrigger', version: 1.2, config: { name: "Daily 10:15 Cairo", parameters: { rule: { interval: [{ field: 'cronExpression', expression: "15 10 * * *" }] } } } });
const queue = node({ type: 'n8n-nodes-base.httpRequest', version: 4.2, config: { name: "Revalidation Queue", retryOnFail: true, maxTries: 3, waitBetweenTries: 2000,
  parameters: { method: 'POST', url: 'https://gagbhykzmtstekpqujyl.supabase.co/rest/v1/rpc/revalidation_queue', authentication: 'predefinedCredentialType', nodeCredentialType: 'supabaseApi',
    sendBody: true, contentType: 'json', specifyBody: 'json', jsonBody: expr("{{ JSON.stringify({ p_limit: 15 }) }}"), options: { timeout: 60000 } },
  credentials: { supabaseApi: { id: 'EkLYXHBGqNUjAGKP', name: 'Supabase account' } } } });
const checks = node({ type: 'n8n-nodes-base.code', version: 2, config: { name: "Build Checks", parameters: { mode: 'runOnceForAllItems', jsCode: "// Drafts older than 14 days are revalidated, never blindly redrafted (Adam, 7 Oct 2026). Deterministic checks come from\n// revalidation_queue (company still qualified, still cold, no new Gmail, no newer duplicate); here we add the date test on the\n// why-now line and build the one search that confirms the person still holds the role.\nvar items = ($input.first().json.items) || [];\nvar MONTHS = { jan: 0, feb: 1, mar: 2, apr: 3, may: 4, jun: 5, jul: 6, aug: 7, sep: 8, sept: 8, oct: 9, nov: 10, dec: 11 };\nvar now = new Date(), year = now.getUTCFullYear();\nfunction latestDate(text) {\n  text = String(text || '');\n  var best = null, m;\n  var re = /\\b(\\d{1,2})(?:\\s*[-\u2013]\\s*(\\d{1,2}))?\\s+(jan|feb|mar|apr|may|jun|jul|aug|sept?|oct|nov|dec)[a-z]*\\.?(?:\\s+(20\\d\\d))?/gi;\n  while ((m = re.exec(text))) {\n    var d = new Date(Date.UTC(m[4] ? +m[4] : year, MONTHS[m[3].toLowerCase()], +(m[2] || m[1])));\n    if (!best || d > best) best = d;\n  }\n  var re2 = /\\b(jan|feb|mar|apr|may|jun|jul|aug|sept?|oct|nov|dec)[a-z]*\\.?\\s+(20\\d\\d)\\b/gi;\n  while ((m = re2.exec(text))) {\n    var d2 = new Date(Date.UTC(+m[2], MONTHS[m[1].toLowerCase()] + 1, 0));\n    if (!best || d2 > best) best = d2;\n  }\n  return best;\n}\nreturn items.map(function (it) {\n  var last = latestDate(it.why_now);\n  var stale = !!(last && last < now);\n  var name = [it.first_name, it.last_name].filter(Boolean).join(' ').trim();\n  var company = String(it.company || '').replace(/\\(.*?\\)/g, ' ').replace(/\"/g, '').replace(/\\s+/g, ' ').trim();\n  var searchable = it.company_relevant && it.relationship_state === 'COLD' && !it.gmail_since && !it.duplicate_open\n    && String(it.first_name || '').length >= 2 && String(it.last_name || '').length >= 2;\n  return { json: Object.assign({}, it, { why_now_stale: stale, why_now_latest: last ? last.toISOString().slice(0, 10) : null,\n    has_name: searchable, q: searchable ? 'site:linkedin.com/in \"' + name + '\" \"' + company + '\"' : '' }) };\n});\n" } } });
const hasName = ifElse({ version: 2.2, config: { name: "Has Name?", parameters: { conditions: { options: { caseSensitive: true, leftValue: '', typeValidation: 'loose' },
  conditions: [{ leftValue: expr("{{ $json.has_name }}"), operator: { type: 'boolean', operation: 'true', singleValue: true } }], combinator: 'and' } } } });
const serper = node({ type: 'n8n-nodes-base.httpRequest', version: 4.2, config: { name: 'Serper Search', onError: 'continueRegularOutput', alwaysOutputData: true,
  parameters: { method: 'POST', url: 'https://google.serper.dev/search', authentication: 'genericCredentialType', genericAuthType: 'httpHeaderAuth',
    sendBody: true, contentType: 'json', specifyBody: 'json', jsonBody: expr('{{ JSON.stringify({ q: $json.q, num: 10 }) }}'),
    options: { batching: { batch: { batchSize: 2, batchInterval: 1500 } } } },
  credentials: { httpHeaderAuth: { id: 'RKkb2wH06uyYl3Zi', name: 'Noya Serper v2' } } } });
const verifyRole = node({ type: 'n8n-nodes-base.code', version: 2, config: { name: "Verify Role", parameters: { mode: 'runOnceForAllItems', jsCode: "// One LinkedIn search per person. STILL_IN_ROLE only when a result's headline carries both the name and the company;\n// MOVED only when the person's headline names another employer and nothing in the result mentions this company;\n// anything else is NOT_FOUND (the draft is kept and the note says the role was not re-confirmed).\nvar src = $('Has Name?').all(0);\nvar STOPW = ('the and of hotel hotels resort resorts group collection travel events company club luxury villa villas residences ' +\n  'international global limited ltd llc inc co uk london dubai').split(' ');\nfunction norm(s) { return String(s || '').toLowerCase().replace(/[\u2019]/g, \"'\").replace(/[^a-z0-9@._' -]/g, ' ').replace(/\\s+/g, ' ').trim(); }\nreturn $input.all().map(function (x, i) {\n  var it = src[i].json, org = (x.json && x.json.organic) || [];\n  var fn = norm(it.first_name), ln = norm(it.last_name);\n  var full = norm(String(it.company).replace(/\\(.*?\\)/g, ' '));\n  var toks = full.split(' ').filter(function (w) { return w.length >= 4 && STOPW.indexOf(w) < 0; });\n  function names(b) { return b.indexOf(full) >= 0 || toks.some(function (w) { return b.indexOf(w) >= 0; }); }\n  var check = 'NOT_FOUND', url = null;\n  for (var k = 0; k < org.length; k++) {\n    var t = norm(org[k].title), s = norm(org[k].snippet);\n    if (t.indexOf(fn) < 0 || t.indexOf(ln) < 0) continue;\n    if (names(t)) { check = 'STILL_IN_ROLE'; url = org[k].link; break; }\n    if (check === 'NOT_FOUND' && / - /.test(org[k].title || '') && !names(s)) { check = 'MOVED'; url = org[k].link; }\n  }\n  return { json: { task_id: it.task_id, role_check: check, evidence_url: url, why_now_stale: it.why_now_stale } };\n});\n" } } });
const noName = node({ type: 'n8n-nodes-base.code', version: 2, config: { name: "Not Searchable", parameters: { mode: 'runOnceForAllItems', jsCode: "// Not searchable (no full name, or the deterministic checks already close it): save with the role not checked.\nreturn $input.all().map(function (x) { return { json: { task_id: x.json.task_id, role_check: 'NOT_CHECKED', evidence_url: null, why_now_stale: x.json.why_now_stale } }; });\n" } } });
const save = node({ type: 'n8n-nodes-base.httpRequest', version: 4.2, config: { name: "Save Revalidation", retryOnFail: true, maxTries: 3, waitBetweenTries: 2000, onError: 'continueRegularOutput',
  parameters: { method: 'POST', url: 'https://gagbhykzmtstekpqujyl.supabase.co/rest/v1/rpc/revalidation_save', authentication: 'predefinedCredentialType', nodeCredentialType: 'supabaseApi',
    sendBody: true, contentType: 'json', specifyBody: 'json', jsonBody: expr("{{ JSON.stringify({ p: $json }) }}"), options: { timeout: 60000 } },
  credentials: { supabaseApi: { id: 'EkLYXHBGqNUjAGKP', name: 'Supabase account' } } } });

export default workflow('noya-20-draft-revalidation', '20 - NOYA Draft Revalidation v1')
  .add(manualRun)
  .to(queue)
  .add(schedule)
  .to(queue)
  .add(queue)
  .to(checks.to(hasName
    .onTrue(serper.to(verifyRole.to(save)))
    .onFalse(noName.to(save))));
